<?php namespace App\Domains\Comercial\LiveSales\Actions; use App\Domains\Auditoria\DTOs\RegistrarAuditoriaData; use App\Domains\Auditoria\Services\RegistrarAuditoriaService; use App\Models\SesionLive; class CambiarEstadoSesionLiveAction{ public function __construct(private RegistrarAuditoriaService $auditoriaService){} public function execute(SesionLive $sesion,string $estado):SesionLive{ $anterior = $sesion->estado_ses; $sesion->update(['estado_ses'=>$estado]); $contexto = RegistrarAuditoriaData::fromRequest(request()); $this->auditoriaService->registrarAccion($contexto, 'LiveSales', 'sesiones_live', (string) $sesion->cod_sesion_live, 'cambio_estado', submodulo: 'Cambio de estado', accionFuncional: 'Cambio de estado de sesión', descripcion: "La sesión #{$sesion->cod_sesion_live} cambió de estado: {$anterior} → {$estado}.", campo: 'estado_ses', valorAnterior: $anterior, valorNuevo: $estado); return $sesion->refresh(); } }
